import {
	ProjectGroupRevisionAction,
	ProjectGroupRevisionStatus,
	type ProjectRevisionStatus
} from '@/generated/graphql'
import { subSeconds } from 'date-fns'
import { reverse } from 'lodash'
import {
	type Edge,
	type TextBlock,
	Item,
	PROJECT_GROUP_CHAT_REVISION_ACTIONS
} from './types'
import { getIdForCommand } from './chat-message-map'
import { splitIntoBlocks } from './cleanup-code'
import { isStatusIndicatingRevisionIsBuilding } from './project-revision'
import { buildCommand } from './build-command'
import { Block } from './types'
import { asEnumValue } from './composition'
import { LLMTag } from './llm-tags'

const createEmail = 'hello@create.xyz'

const shouldDelayEntrance = (node: Edge['node'], block: TextBlock) => {
	return (
		block.type === 'text' &&
		node.action === ProjectGroupRevisionAction.FORK_WITH_CHAT_MESSAGE &&
		subSeconds(new Date(), 10) < new Date(node.createdAt)
	)
}
const TYPING_INTERVAL_MS = 45
const INITIAL_DELAY_MS = 400

export const getMessagesFromRevisions = ({
	edges,
	latestRevision,
	submittingCommand,
	error,
	linkableElementSelected
}: {
	edges: Edge[]
	latestRevision?: {
		id: string
		status: ProjectRevisionStatus | ProjectGroupRevisionStatus
	}
	submittingCommand: string | null
	error: { moduleId: string; message: string } | null
	linkableElementSelected: boolean
}): Item[] => {
	const latestChatRevision = edges.find(({ node }) =>
		PROJECT_GROUP_CHAT_REVISION_ACTIONS.includes(node.action)
	)?.node

	const filteredLatestRevision = latestChatRevision
		? {
				id: latestChatRevision.id,
				status: latestChatRevision.status
		  }
		: latestRevision

	let foundSubmitting = false
	const messages = reverse(
		edges.flatMap(({ node }): Item[] => {
			switch (node.action) {
				case ProjectGroupRevisionAction.SELECT_INTEGRATION_WITH_CHAT_MESSAGE:
				case ProjectGroupRevisionAction.PUBLISH_PROJECT_AND_CONTINUE_CHAT:
				case ProjectGroupRevisionAction.CHANGE_DESIGN_SYSTEM_AND_CONTINUE_CHAT:
				case ProjectGroupRevisionAction.SAVE_SECRET_AND_CONTINUE_CHAT:
				case ProjectGroupRevisionAction.FORK_WITH_CHAT_MESSAGE:
				case ProjectGroupRevisionAction.FORK_MODULE_WITH_CHAT_MESSAGE:
				case ProjectGroupRevisionAction.ADD_AUTH_AND_CONTINUE_CHAT:
				case ProjectGroupRevisionAction.CHAT:
				case ProjectGroupRevisionAction.DEEP_DEBUGGING: // @TODO: Determine if relevant for deep debugging mode
				case ProjectGroupRevisionAction.EXPERT_SWE:
				case ProjectGroupRevisionAction.AUTO_SELECT_CHAT:
				case ProjectGroupRevisionAction.DISCUSSION: {
					const command =
						node.action ===
						ProjectGroupRevisionAction.ADD_AUTH_AND_CONTINUE_CHAT
							? null
							: buildCommand({
									node,
									latestRevisionId: filteredLatestRevision?.id ?? null
							  })

					if (node.chat && node.chat.content === submittingCommand) {
						foundSubmitting = true
					}
					const prologue: Item[] =
						node.action ===
						ProjectGroupRevisionAction.ADD_AUTH_AND_CONTINUE_CHAT
							? [
									{
										type: 'message',
										data: {
											id: node.id,
											actor: 'assistant' as const,
											action: node.action,
											blocks: [
												{
													type: 'tombstone',
													code: 'User accounts were enabled',
													lang: 'unknown',
													isPartial: false
												}
											],
											isLatest: node.id === filteredLatestRevision?.id,
											isGenerating: false,
											revision: {
												type: 'project-group',
												id: node.id,
												createdAt: new Date(node.createdAt),
												previewURL: node.previewURL ?? null,
												status: node.status
											}
										}
									}
							  ]
							: []

					if (!node.response) {
						if (
							'status' in node &&
							node.status === ProjectGroupRevisionStatus.INVALID
						) {
							return [
								{
									type: 'message',
									data: {
										id: node.id,
										actor: 'assistant' as const,
										action: node.action,
										blocks: [
											{
												lang: 'unknown',
												code: `I'm having trouble generating this request. If there is an ongoing system-wide problem, updates can be found on [our status page](https://status.create.xyz/). If the issue persists, reach out to [${createEmail}](mailto:${createEmail}) and we'll get it fixed.`,
												isPartial: false,
												type: 'text'
											}
										],
										isLatest: node.id === filteredLatestRevision?.id,
										isGenerating:
											node.id === filteredLatestRevision?.id &&
											isStatusIndicatingRevisionIsBuilding(node.status),
										revision: {
											type: 'project-group',
											id: node.id,
											createdAt: new Date(node.createdAt),
											previewURL: node.previewURL ?? null,
											status: node.status
										}
									}
								},
								...(command ? [command] : []),
								...prologue
							]
						}
						const isLatest = node.id === filteredLatestRevision?.id
						const assistantBlocks: Block[] = []

						return [
							{
								type: 'message',
								data: {
									id: node.id,
									actor: 'assistant' as const,
									action: node.action,
									blocks: assistantBlocks,
									isLatest,
									isGenerating:
										node.id === filteredLatestRevision?.id &&
										isStatusIndicatingRevisionIsBuilding(node.status),
									revision:
										node.__typename === 'ProjectGroupRevision'
											? {
													type: 'project-group',
													id: node.id,
													createdAt: new Date(node.createdAt),
													previewURL: node.previewURL ?? null,
													status: node.status
											  }
											: null
								}
							},
							...(command ? [command] : []),
							...prologue
						]
					}
					const blocks = splitIntoBlocks(node.response, Object.values(LLMTag))
					// we want to create new messages after the block code block is
					// done.
					const groups = blocks.reduce((acc, block): TextBlock[][] => {
						const last = acc[acc.length - 1]
						const rest = acc.slice(0, acc.length - 1)
						if (!last) {
							return [...rest, [block]] as TextBlock[][]
						}
						if (last.some((b) => b.type === 'code')) {
							return [...rest, last, [block]] as TextBlock[][]
						}
						return [...rest, [...last, block]] as TextBlock[][]
					}, new Array<TextBlock[]>()) as TextBlock[][]
					if (groups.length === 0) {
						const isLatest = node.id === filteredLatestRevision?.id
						return [
							{
								type: 'message',
								data: {
									id: node.id,
									actor: 'assistant' as const,
									action: node.action,
									blocks: [],
									isLatest,
									isGenerating:
										node.id === filteredLatestRevision?.id &&
										isStatusIndicatingRevisionIsBuilding(node.status),
									revision:
										node.__typename === 'ProjectGroupRevision'
											? {
													type: 'project-group',
													id: node.id,
													createdAt: new Date(node.createdAt),
													previewURL: node.previewURL ?? null,
													status: node.status
											  }
											: null
								}
							},
							...(command ? [command] : []),
							...prologue
						]
					}

					const isLatest = node.id === filteredLatestRevision?.id
					const isGenerating = filteredLatestRevision
						? isStatusIndicatingRevisionIsBuilding(
								filteredLatestRevision.status
						  )
						: false

					return [
						{
							type: 'message' as const,
							data: {
								id: node.id,
								actor: 'assistant' as const,
								action: node.action,
								blocks: groups.flatMap((b) => {
									return b.map((block, index): Block => {
										if (block.type === 'tag') {
											const tag = asEnumValue(block.tag, LLMTag)
											if (!tag) {
												return {
													type: 'text',
													code: block.content,
													lang: 'unknown',
													isPartial: false
												}
											}
											if (
												[
													LLMTag.MODULE_SELECTION,
													LLMTag.INTEGRATION_SELECTION
												].includes(tag)
											) {
												const previous = b[index - 1]
												if (previous && shouldDelayEntrance(node, previous)) {
													const wordCount = previous.content.split(' ').length
													return {
														type: block.type,
														tag,
														code: block.content,
														args: block.args,
														delayMs:
															800 +
															INITIAL_DELAY_MS +
															wordCount * TYPING_INTERVAL_MS
													}
												}
											}
											return {
												type: block.type,
												tag: block.tag as LLMTag,
												code: block.content,
												args: block.args
											}
										}

										if (index === 0 && shouldDelayEntrance(node, block)) {
											return {
												type: 'animated-text' as const,
												text: block.content,
												delayMs: INITIAL_DELAY_MS,
												typingIntervalMs: TYPING_INTERVAL_MS,
												breakOnSpaces: true
											}
										}

										return {
											lang:
												block.type === 'code'
													? block.language ?? 'unknown'
													: 'unknown',
											code: block.content,
											isPartial:
												block.type === 'code' && isLatest && isGenerating
													? block.isPartial
													: false,
											type: block.type
										}
									})
								}),
								isLatest,
								isGenerating:
									node.id === filteredLatestRevision?.id &&
									isStatusIndicatingRevisionIsBuilding(node.status),
								revision:
									node.__typename === 'ProjectGroupRevision'
										? ({
												type: 'project-group' as const,
												id: node.id,
												createdAt: new Date(node.createdAt),
												previewURL: node.previewURL ?? null,
												status: node.status
										  } as const)
										: null
							}
						},
						...(command ? [command] : []),
						...prologue
					]
				}
				case ProjectGroupRevisionAction.AGENT_AUTO_SELECT_INTEGRATION:
				case ProjectGroupRevisionAction.UPDATE_AUTH_SETTINGS:
				case ProjectGroupRevisionAction.UPDATE_EXPO_SETTINGS:
				case ProjectGroupRevisionAction.DUPLICATE:
				case ProjectGroupRevisionAction.FORK:
				case ProjectGroupRevisionAction.PROJECT_INITIAL:
				case ProjectGroupRevisionAction.PROJECT_RESTORE:
				case ProjectGroupRevisionAction.PROJECT_DELETION:
				case ProjectGroupRevisionAction.PROJECT_UI_PATCH:
				case ProjectGroupRevisionAction.PROJECT_CREATE_COMPONENT_FROM_PROMPT:
				case ProjectGroupRevisionAction.PROJECT_CREATE_COMPONENT_FROM_PROMPT_AND_CODE:
				case ProjectGroupRevisionAction.PROJECT_APPLY_COMMAND:
				case ProjectGroupRevisionAction.PROJECT_CHANGE_AUTH:
				case ProjectGroupRevisionAction.PROJECT_CODE_CHANGE:
				case ProjectGroupRevisionAction.PROJECT_DUPLICATE_MODULE:
				case ProjectGroupRevisionAction.PROJECT_DUPLICATE_PROJECT_GROUP:
				case ProjectGroupRevisionAction.PROJECT_FIX_CHANGE:
				case ProjectGroupRevisionAction.PROJECT_FORK_FROM_PROJECT_GROUP:
				case ProjectGroupRevisionAction.PROJECT_FORK_FROM_PROJECT_GROUP_TEMPLATE:
				case ProjectGroupRevisionAction.PROJECT_IMAGE_CHANGE:
				case ProjectGroupRevisionAction.PROJECT_LINK_CHANGE:
				case ProjectGroupRevisionAction.PROJECT_REBUILD_FROM_LATEST:
				case ProjectGroupRevisionAction.PROJECT_TEXT_CHANGE:
				case ProjectGroupRevisionAction.PROJECT_UPDATE_REFERENCES:
				case ProjectGroupRevisionAction.INTRODUCE_BUG:
				case ProjectGroupRevisionAction.JUDGE_DEEP_DEBUGGING:
				case ProjectGroupRevisionAction.EXTERNAL_UPDATE:
				case ProjectGroupRevisionAction.ORCHESTRATOR:
				case ProjectGroupRevisionAction.DELEGATE_TO_SUB_AGENT:
				case ProjectGroupRevisionAction.BRIDGE_LEGACY_PROJECT_GROUP_TO_FILE_BASED:
				case ProjectGroupRevisionAction.DESIGN_AGENT:
				case ProjectGroupRevisionAction.PLAN_AGENT:
					return []
				case ProjectGroupRevisionAction.RESTORE:
					return [
						{
							type: 'message',
							data: {
								id: node.id,
								actor: 'assistant' as const,
								action: node.action,
								blocks: [
									{
										type: 'tombstone',
										code: 'A previous version was restored',
										lang: 'unknown',
										isPartial: false
									}
								],
								isLatest: node.id === filteredLatestRevision?.id,
								isGenerating: false,
								revision: {
									type: 'project-group',
									id: node.id,
									createdAt: new Date(node.createdAt),
									previewURL: node.previewURL ?? null,
									status: node.status
								}
							}
						}
					]
				default: {
					const exhaust: never = node.action
					return exhaust
				}
			}
		})
	)
	if (!foundSubmitting && submittingCommand) {
		messages.push(
			{
				type: 'message',
				data: {
					id: getIdForCommand(submittingCommand),
					actor: 'user',
					action: null,
					blocks: splitIntoBlocks(submittingCommand).map((block) => ({
						code: block.type === 'tag' ? '' : block.content,
						lang:
							block.type === 'code' ? block.language ?? 'unknown' : 'unknown',
						isPartial: false,
						type: block.type === 'tag' ? 'text' : block.type
					})),
					isLatest: true,
					isGenerating: false,
					revision: null
				}
			},
			{
				type: 'message',
				data: {
					id: getIdForCommand(submittingCommand),
					actor: 'assistant',
					action: null,
					blocks: [],
					isLatest: true,
					isGenerating: true,
					revision: null
				}
			}
		)
	}
	if (error) {
		const lastMessage = messages[messages.length - 1]
		if (
			lastMessage &&
			lastMessage.type === 'message' &&
			'data' in lastMessage
		) {
			lastMessage.data.isLatest = false
		}

		messages.push({
			type: 'message',
			data: {
				id: error.moduleId,
				actor: 'assistant',
				action: null,
				blocks: [
					{
						type: 'error',
						code: error.message,
						lang: 'unknown',
						isPartial: false
					}
				],
				isLatest: true,
				isGenerating: false,
				revision: null
			}
		})
	} else if (linkableElementSelected) {
		// messages.push({
		// 	type: 'app-builder-selection',
		// 	selected: linkableElementSelected
		// })
	}
	return messages
}
